(() => {
"use strict";
const U=window.DW_UI,V=window.DW_VIEWS,{esc,icon,btn,pill,notice,table,section,shell}=U;
const DS=window.DW_DESIGN_STATE=window.DW_DESIGN_STATE||{};
const P=DS.platform={};
const clone=value=>JSON.parse(JSON.stringify(value));
const labels={"capture.display":"显示屏截图","capture.window":"窗口截图","record.pointerAbsolute":"鼠标轨迹录制","record.pointerRelative":"相对移动录制","record.keyboard":"键盘录制","record.allDisplays":"全部显示屏录制","input.pointerAbsolute":"鼠标定位与绘制","input.pointerRelative":"相对移动","input.keyboard":"键盘输入","input.unicodeText":"Unicode 文本","control.globalShortcut":"全局急停快捷键","control.focusTarget":"切换目标窗口"};
const stateText={available:'可用',permissionRequired:'需要授权',denied:'未获授权',unsupported:'当前会话不支持',unimplemented:'当前组件未提供',sessionUnavailable:'会话不可用'};
const action=(label,name,kind='',extra='')=>'<button type="button" class="btn '+kind+'" data-pf-action="'+name+'" '+extra+'>'+esc(label)+'</button>';
const panel=(title,body,extra='')=>'<section class="panel '+extra+'"><div class="panel-head">'+title+'</div><div class="panel-body">'+body+'</div></section>';
function reset(id){const F=window.DW_CATALOG.platformFixtures;P.capabilities=clone(F[id.includes('wayland')?'wayland-capabilities':id==='platform-macos-permissions'?'macos-permissions':'macos-capabilities']);P.granted={screen:id!=='platform-macos-permissions',listen:id!=='platform-macos-permissions',access:id!=='platform-macos-permissions'};P.selected=['main','left'];P.message='';P.error='';P.mapping={main:'linux-main',left:'linux-left'};P.mappingOutput=null;}
const previous=DS.resetForScreen;DS.resetForScreen=id=>{previous?.(id);if(id.startsWith('platform-')||!P.capabilities)reset(id);};
function hero(title,subtitle,badge,ico='target'){return '<div class="pf-hero"><div class="pf-hero-icon">'+icon(ico,30)+'</div><div class="pf-hero-copy"><span class="eyebrow">桌面环境</span><h3>'+esc(title)+'</h3><p>'+esc(subtitle)+'</p></div>'+pill(badge,'blue')+'</div>';}
function page(s,body,actions='',mac=false){let html=shell(s,'<main class="page pf-page">'+section(s.title,'设置 / 桌面与系统权限',actions||btn('返回设置','settings-general'))+body,{active:'settings'});if(mac){html=html.replace('<div class="window-controls"><span>—</span><span>□</span><span>×</span></div>','<div class="window-controls pf-mac-controls"><span></span><span></span><span></span></div>').replace('急停 <kbd>Ctrl</kbd> + <kbd>Alt</kbd> + <kbd>Pause</kbd>','急停 <kbd>⌃</kbd> + <kbd>⌥</kbd> + <kbd>F12</kbd>');}return html;}
function capabilityTable(){return table(['桌面操作','状态'],Object.entries(P.capabilities.features).map(([key,value])=>[esc(labels[key]),pill(stateText[value.state],value.state==='available'?'green':value.state==='permissionRequired'?'amber':'')]));}
function capabilities(s){const pending=Object.values(P.capabilities.features).filter(f=>f.state==='permissionRequired').length,recordReady=P.capabilities.features['record.allDisplays'].state==='available';return page(s,hero('macOS · Apple Silicon',pending?pending+' 项操作需要系统授权':'2 个显示屏 · 屏幕与输入权限已就绪',pending?'需要设置':'已连接')+'<div class="pf-columns">'+panel('当前可用能力',capabilityTable(),'pf-table-panel')+'<aside class="stack">'+panel('录制与绘制','<div class="pf-summary"><strong>全部 2 个显示屏</strong><p>跨屏移动、拖拽与键盘操作使用同一条时间轴。</p></div>'+notice(recordReady?'可以开始录制':'录制需要输入监听',recordReady?'鼠标按住期间完整记录每个中间位置。':'允许输入监听后重新检查。',recordReady?'green':'amber')+'<div class="pf-actions">'+btn('管理系统权限','platform-macos-permissions','primary','shield')+'</div>')+panel('轨迹与屏幕','<div class="pf-fact"><span>内建显示屏</span><strong>3024 × 1964</strong></div><div class="pf-fact"><span>左侧显示屏</span><strong>1920 × 1080</strong></div><div class="pf-fact"><span>回放方式</span><strong>按显示屏像素映射</strong></div><div class="pf-actions">'+btn('查看跨平台映射','platform-display-mapping','','target')+'</div>')+'</aside></div>','',true);}
const permissionGroups={screen:['capture.display','capture.window'],listen:['record.pointerAbsolute','record.pointerRelative','record.keyboard'],access:['input.pointerAbsolute','input.pointerRelative','input.keyboard','input.unicodeText']};
function updatePermissions(){for(const [group,keys]of Object.entries(permissionGroups)){for(const key of keys)P.capabilities.features[key]=P.granted[group]?{state:'available',reason:'NONE',nextAction:'none'}:{state:'permissionRequired',reason:'PERMISSION_MISSING',nextAction:'grantPermission'};}const complete=P.granted.listen;P.capabilities.features['record.allDisplays']=complete?{state:'available',reason:'NONE',nextAction:'none'}:{state:'permissionRequired',reason:'PERMISSION_MISSING',nextAction:'grantPermission'};P.capabilities.generation++;}
function permissions(s){const cards=[['screen','屏幕录制','允许获取已选择显示屏或窗口的图像。','image'],['listen','输入监听','记录鼠标轨迹、按钮与键盘操作。','mouse'],['access','辅助功能','执行已授权的指针和键盘操作。','shield']].map(([key,title,desc,ico])=>'<div class="pf-permission"><span class="pf-permission-icon">'+icon(ico,23)+'</span><div><h3>'+title+'</h3><p>'+desc+'</p><span>'+pill(P.granted[key]?'已允许':'需要授权',P.granted[key]?'green':'amber')+'</span></div>'+action(P.granted[key]?'重新检查':'检查授权状态','check-permission',P.granted[key]?'small':'small primary','data-pf-permission="'+key+'"')+'</div>').join('');return page(s,hero('macOS 隐私与安全性','权限按操作用途分别设置','系统权限','shield')+'<div class="pf-columns"><div class="stack">'+panel('系统权限',cards)+(P.message?notice('权限状态已更新',P.message,'green'):'')+'</div><aside class="stack">'+panel('授权后继续','<ol class="pf-steps"><li><span>1</span><div><strong>打开系统设置</strong><p>在“隐私与安全性”中选择对应权限。</p></div></li><li><span>2</span><div><strong>允许 DeskWeaveStudio</strong><p>分别设置屏幕录制、输入监听与辅助功能。</p></div></li><li><span>3</span><div><strong>重新检查状态</strong><p>返回工作台，更新当前可用操作。</p></div></li></ol>')+panel('录制状态',notice(P.capabilities.features['record.allDisplays'].state==='available'?'可以录制全部显示屏':'录制需要输入监听',P.capabilities.features['record.allDisplays'].state==='available'?'已取得完整鼠标与键盘事件的录制权限。':'允许输入监听后重新检查。',P.capabilities.features['record.allDisplays'].state==='available'?'green':'amber')+'<div class="pf-actions">'+btn('查看桌面能力','platform-capabilities')+'</div>')+'</aside></div>','',true);}
function monitors(topology){const displays=topology.displays,rects=displays.map(d=>d.layoutBounds),x=Math.min(...rects.map(r=>r.x)),y=Math.min(...rects.map(r=>r.y)),width=Math.max(...rects.map(r=>r.x+r.width))-x,height=Math.max(...rects.map(r=>r.y+r.height))-y;return '<div class="pf-monitor-stage"><div class="pf-monitor-plane" style="width:min(92%,'+(180*width/height)+'px);aspect-ratio:'+width+'/'+height+'">'+displays.map(d=>{const r=d.layoutBounds;return '<div class="pf-monitor" style="left:'+(100*(r.x-x)/width)+'%;top:'+(100*(r.y-y)/height)+'%;width:'+(100*r.width/width)+'%;height:'+(100*r.height/height)+'%"><span>'+esc(d.name)+'</span><strong>'+d.pixelSize.width+' × '+d.pixelSize.height+'</strong><i></i></div>';}).join('')+'</div></div>';}

function wayland(s){const count=P.selected.length;return page(s,hero('Linux · Wayland','已建立屏幕共享与输入控制会话','会话已连接')+'<div class="pf-columns"><div class="stack">'+panel('已选择的显示屏',monitors(window.DW_CATALOG.platformFixtures['context-cross-backend'].topology)+'<div class="pf-screen-options">'+[['main','主显示屏','3024 × 1964'],['left','左侧显示屏','1920 × 1080']].map(([id,title,size])=>'<label><input type="checkbox" data-pf-display="'+id+'" '+(P.selected.includes(id)?'checked':'')+'><div><strong>'+title+'</strong><small>'+size+'</small></div>'+pill('可用于截图与控制','blue')+'</label>').join('')+'</div>')+(P.message?notice('屏幕选择已更新',P.message,'green'):'')+'</div><aside class="stack">'+panel('当前范围','<div class="pf-summary"><strong>选中 '+count+' 个显示屏</strong><p>使用本次系统选择器授权的显示范围。</p></div><div class="pf-fact"><span>屏幕截图</span>'+pill('可用','green')+'</div><div class="pf-fact"><span>鼠标与键盘控制</span>'+pill('可用','green')+'</div><div class="pf-actions">'+action('使用所选屏幕','select-screens','primary',count?'':'disabled')+'</div>')+panel('键鼠操作录制',notice('当前会话不提供全局录制','屏幕共享与输入控制已可用。','amber')+'<div class="pf-actions">'+btn('查看录制条件','platform-wayland-recording')+'</div>')+'</aside></div>');}
function recording(s){return page(s,hero('Linux · Wayland','键鼠操作录制','当前会话不支持','record')+'<div class="pf-columns"><div class="stack">'+panel('全部显示屏录制','<div class="pf-unavailable"><span>'+icon('record',36)+'</span><h3>当前桌面会话未提供完整键鼠事件</h3><p>录制绘图需要持续取得每个鼠标位置、按住状态与键盘事件。</p></div>'+notice('需要支持全局录制的桌面会话','当前会话的屏幕共享不能提供这条录制事件流。','amber'))+panel('仍可使用',table(['操作','当前状态'],[['编辑流程与轨迹',pill('可用','green')],['所选屏幕截图',pill('可用','green')],['所选屏幕输入控制',pill('可用','green')]]))+'</div><aside class="stack">'+panel('继续操作','<div class="pf-summary"><strong>保留当前流程与资产</strong><p>可以继续编辑，或在具备全局录制能力的桌面会话中开始录制。</p></div><div class="pf-actions pf-actions-vertical">'+btn('返回会话设置','platform-wayland-session','primary')+btn('打开轨迹资产','assets')+'</div>')+'</aside></div>');}
function mappingErrors(){const F=window.DW_CATALOG.platformFixtures,C=F['context-cross-backend'],source=C.trajectory.source,targets=C.topology.displays;const result=[];if(new Set(Object.values(P.mapping)).size!==source.displayIds.length)result.push('每个来源显示屏需要映射到不同的当前屏幕。');for(const point of C.trajectory.events.filter(e=>e.kind==='pointer.move')){const target=targets.find(d=>d.displayId===P.mapping[point.displayId]);if(target&&target.pixelToNative===null)result.push('当前显示屏的输入映射已失效，请重新选择。');if(!target||point.x<0||point.y<0||point.x>=target.pixelSize.width||point.y>=target.pixelSize.height)result.push('轨迹位置超出所选显示屏。');}return [...new Set(result)];}
function mapping(s){const C=window.DW_CATALOG.platformFixtures['context-cross-backend'],source=C.trajectory.source,errors=mappingErrors();return page(s,hero('将 macOS 轨迹用于 Linux','按屏内像素绑定显示屏，保留原笔画','2 个来源显示屏','link')+'<div class="pf-columns"><div class="stack">'+panel('录制来源',monitors(source.topology)+'<div class="pf-fact"><span>坐标单位</span><strong>显示屏内的图像像素</strong></div><div class="pf-fact"><span>输入内容</span><strong>跨屏持续拖动 · 完整点列</strong></div>')+notice('保持屏内像素偏移','原轨迹不自动缩放或改变形状。','blue')+'</div><aside class="stack">'+panel('选择当前显示屏',source.topology.displays.map(d=>'<label class="field"><span class="field-label">'+esc(d.name)+' · '+d.pixelSize.width+' × '+d.pixelSize.height+'</span><select data-pf-map="'+d.displayId+'">'+C.topology.displays.map(t=>'<option value="'+t.displayId+'" '+(P.mapping[d.displayId]===t.displayId?'selected':'')+'>'+esc(t.name)+' · '+t.pixelSize.width+' × '+t.pixelSize.height+'</option>').join('')+'</select></label>').join(''))+panel('准备结果',errors.length?notice('需要调整映射',errors.join(''),'amber'):notice(P.mappingOutput?'映射已应用':'所有位置均在目标范围内',P.mappingOutput?'可以在当前授权目标中使用这条轨迹。':'两个来源显示屏均已对应到当前屏幕。','green'))+'<div class="pf-actions">'+action('应用显示屏映射','apply-mapping','primary',errors.length?'disabled':'')+'</div></aside></div>');}
V.platform=s=>s.variant==='permissions'?permissions(s):s.variant==='wayland'?wayland(s):s.variant==='recording'?recording(s):s.variant==='mapping'?mapping(s):capabilities(s);
document.addEventListener('change',event=>{const input=event.target;if(input.matches('[data-pf-display]')){P.selected=input.checked?[...new Set([...P.selected,input.dataset.pfDisplay])]:P.selected.filter(id=>id!==input.dataset.pfDisplay);P.message='';window.DW_PROTOTYPE.go('platform-wayland-session');}if(input.matches('[data-pf-map]')){P.mapping[input.dataset.pfMap]=input.value;P.mappingOutput=null;window.DW_PROTOTYPE.go('platform-display-mapping');}},true);
document.addEventListener('click',event=>{const button=event.target.closest('[data-pf-action]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();switch(button.dataset.pfAction){case'check-permission':P.granted[button.dataset.pfPermission]=true;updatePermissions();P.message='已重新读取所选权限，其他权限保持各自状态。';window.DW_PROTOTYPE.go('platform-macos-permissions');break;case'select-screens':if(P.selected.length){P.capabilities.topologyCoverage='selected';P.capabilities.generation++;P.message='已选择 '+P.selected.length+' 个显示屏，用于截图与输入控制。';window.DW_PROTOTYPE.go('platform-wayland-session');}break;case'apply-mapping':if(!mappingErrors().length){P.mappingOutput={mode:'displayLocal',displays:Object.entries(P.mapping).map(([sourceDisplayId,targetDisplayId])=>({sourceDisplayId,targetDisplayId}))};window.DW_PROTOTYPE.go('platform-display-mapping');}break;}},true);
window.DW_PLATFORM={mappingErrors};
})();
